let pos, vel, axis, twist, x_off, y_off, particle_count;

const particle_limit = 50;
const trail_limit = 10000;

function setup() {
	createCanvas(windowWidth, windowHeight);
	background("#e4e7e0");
	noStroke();
	x_off = randomGaussian(0.5 * width, 0.05 * width);
	y_off = randomGaussian(0.5 * height, 0.05 * height);
	particle_count = 0;
	graticule();
}

function draw() {
	if (particle_count > particle_limit) return;

	grunge();

	particle_count++;
	translate(x_off, y_off);
	pos = createVector(0, 0, 0);
	vel = p5.Vector.random3D();
	axis = createVector(random(-0.1, 0.1), random(-0.1, 0.1), 1).normalize();
	twist = random(-0.02, 0.02);

	trail = 0;
	while (abs(pos.z) < 200) {
		bubble(pos.x, pos.y, random(0, 8));
		let step = p5.Vector.mult(vel, random(1, 2));
		pos.add(step);
		pos = rotateVectorAroundAxis(pos, axis, twist);
		if (abs(pos.x) > width || abs(pos.y) > height) {
			pos.z = 99999;
		}
		if (trail++ > trail_limit) pos.z = 99999;
		twist *= 1.0001;
	}
	//move position
	if (pow(random(1), 0.3) < (particle_count / particle_limit)) {
		x_off = random(width);
		y_off = random(height);
	}
}

function bubble(x, y, r) {
	fill("#61026201");
	circle(x, y, r * 4);
	fill("#61024410");
	circle(x, y, r);
	fill("#210b2220");
	circle(x, y, r / 2);
	fill("#15011c30");
	circle(x, y, r / 4);
}

function grunge() {
	push();
	let y = random(height);
	let dist = random(pow((1 - y / height), 4) * width) * 0.7;
	fill("#31023206");

	//light bleed
	for (let x = 0; x < dist; x += 5) {
		for (let i = 0; i < dist - x; i += 10) {
			circle(x + random(-15, 15), y + random(-50 * pow((1 - x / dist), 2), 50 * pow((1 - x / dist), 2)), randomGaussian(0, 4));
			circle(width - x + random(-15, 15), height - y + random(-50 * pow((1 - x / dist), 2), 50 * pow((1 - x / dist), 2)), randomGaussian(0, 4));
		}
	}

	//blotches
	let x = random(width);
	y = random(height);
	for (let i = 0; i < 200; i++) {
		circle(randomGaussian(x, width / 50), randomGaussian(y, height / 1000), 3);
	}

	//more blotches
	fill("#31023240");
	for (let i = 0; i < 500; i++) {
		circle(random(width), random(height), 0.5);
	}

	//more scratches
	noFill();
	strokeWeight(0.2)
	stroke("#31023210");
	for (let i = 0; i < 10; i++) {
		line(random(width), random(height), random(width), random(height));
	}

	pop();
}

function graticule(minCells = 3, plusScale = 0.1) {

  // Cell size based on shorter dimension
  const spacing = min(width, height) / minCells;

  // Number of cells needed to cover canvas
  const cols = ceil(width / spacing) + 1;
  const rows = ceil(height / spacing) + 1;

  const plusSize = spacing * plusScale;

	push();
	stroke("#31023250");
  for (let row = 0; row < rows; row++) {
    for (let col = 0; col < cols; col++) {

      const x = col * spacing + spacing / 2;
      const y = row * spacing + spacing / 2;

      line(x - plusSize / 2, y, x + plusSize / 2, y);
      line(x, y - plusSize / 2, x, y + plusSize / 2);
    }
  }
	pop();
}

function rotateVectorAroundAxis(v, axis, angle) { //Rodrigues' rotation formula
	let k = axis.copy().normalize();
	let vCos = v.copy().mult(cos(angle));
	let kCrossV = k.copy().cross(v).mult(sin(angle));
	let kDotV = k.dot(v);
	let kDotTerm = k.copy().mult(kDotV * (1 - cos(angle)));
	return vCos.add(kCrossV).add(kDotTerm);
}

function windowResized() {
	setup();
}

//disable default right mouse click
try { document.addEventListener("contextmenu", (event) => event.preventDefault(), true); } catch(e){}

//left click restarts, right click does an image capture
let lapse = 0; // mouse timer
function mousePressed() {
	if (millis() - lapse > 400) {
		lapse = millis();
		if (mouseButton === RIGHT) {
			save("img_" + year() + nf(month(), 2) + nf(day(), 2) + nf(hour(), 2) + nf(minute(), 2) + nf(second(), 2) + ".png");
		} else if (mouseButton === LEFT) {
			setup();
		} else {}
	}
	return (false)
}

